BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Written representations cannot substitute for other audit procedures
(1, 'Written Representations', 'During the audit of Keystone Corp. for the year ended December 31, 2025, a staff auditor at Thornton & Marks CPA proposes relying solely on the management representation letter to support a $2.4 million receivable balance, noting that management confirmed its validity in writing. The engagement partner explains the proper role of written representations. Under AU-C 580, written representations:', '["Cannot serve as a substitute for other audit procedures the auditor determines are necessary", "Provide sufficient evidence to eliminate the need for additional testing of balances specifically confirmed in the letter", "Replace external confirmations when management has demonstrated consistent reliability over multiple audit cycles", "Serve as the primary source of evidence when the auditor assesses inherent risk as low"]'::jsonb, 0, 'Under AU-C 580.04, written representations are necessary audit information but do not provide sufficient appropriate audit evidence on their own about any matter they address. They complement, rather than replace, other audit procedures. Unlike choice B suggests, management''s written confirmation of receivable validity does not eliminate the need for confirmations, vouching, or other substantive procedures required to support the assertion.', 'medium', 2),

-- Q2: easy / L1 — Addressee of the management representation letter
(1, 'Written Representations', 'To whom is the management representation letter typically addressed?', '["The entity''s board of directors or audit committee", "The engagement partner or the audit firm", "The SEC or other regulatory agency overseeing the entity", "The entity''s external legal counsel"]'::jsonb, 1, 'Under AU-C 580.14, the management representation letter is addressed to the auditor — specifically to the engagement partner or the audit firm performing the audit. The letter confirms management''s assertions directly to the auditor. Unlike choice A suggests, the letter is not addressed to the board or audit committee, even though those parties may have governance oversight responsibilities.', 'easy', 1),

-- Q3: medium / L2 — Period covered by the management representation letter
(1, 'Written Representations', 'Barrett & Webb CPA is auditing Meridian Industries'' financial statements for the year ended December 31, 2025. The prior year was audited by a different firm. The controller asks what time period the management representation letter should cover. Under AU-C 580, the representation letter should cover:', '["Only the current year being audited, since the predecessor audited the prior year", "The current year plus a lookback period of at least two additional years", "All periods referred to in the auditor''s report", "Only transactions occurring after the prior auditor''s report date"]'::jsonb, 2, 'Under AU-C 580.15, the management representation letter covers all periods referred to in the auditor''s report. Even if a predecessor auditor performed the prior-year audit, the current auditor''s report references both years in comparative financial statements. Unlike choice A suggests, limiting the letter to only the current year would leave the auditor without necessary representations for prior-period comparatives included in the report.', 'medium', 2),

-- Q4: easy / L1 — Written vs. oral representations
(1, 'Written Representations', 'Under AU-C 580, why must management representations be obtained in written form?', '["Written form is optional as long as oral representations are documented in the workpapers", "Written form is required only for representations about fraud and illegal acts", "Written form is required solely to satisfy regulatory filing requirements", "Written form reduces misunderstandings and provides documentary evidence of the representations made"]'::jsonb, 3, 'Under AU-C 580.09, the auditor requests written representations to reduce the possibility of misunderstanding between the auditor and management and to provide documentary evidence that representations were made. Oral representations alone are insufficient under the standard. Unlike choice A suggests, documenting oral representations in workpapers does not satisfy AU-C 580''s requirement that management provide representations in a written letter.', 'easy', 1),

-- Q5: easy / L1 — Definition of written representations
(1, 'Written Representations', 'Under AU-C 580, what are written representations from management?', '["Written statements provided by management to the auditor to confirm certain matters or support other audit evidence", "Formal certifications filed with the SEC by officers of publicly traded companies", "Internal memos circulated among management documenting accounting policy decisions", "Engagement letters signed by management to authorize the commencement of the audit"]'::jsonb, 0, 'Under AU-C 580.07, written representations are written statements by management provided to the auditor to confirm certain matters or to support other audit evidence. They are a form of audit evidence specific to the audit engagement. Unlike choice D suggests, an engagement letter establishes the terms of the audit and is a separate document from the representation letter, which addresses management''s assertions and acknowledgments.', 'easy', 1),

-- Q6: medium / L2 — Completeness of transactions representation
(1, 'Written Representations', 'While preparing the representation letter for the December 31, 2025 audit of Cascade Financial Services, the controller at Donovan & Clark CPA asks which representation specifically addresses the risk that transactions may have been omitted from the accounting records. The representation that directly addresses this risk states that management has:', '["Provided the auditor with access to all financial records and data as requested", "Recorded all transactions in the accounting records and reflected them in the financial statements", "Maintained effective internal controls over the financial reporting process", "Selected and applied all accounting policies on a basis consistent with the prior year"]'::jsonb, 1, 'Under AU-C 580.11, management must represent that all transactions have been recorded and are reflected in the financial statements, directly addressing the completeness assertion. This representation targets the risk that transactions were omitted. Unlike choice A suggests, providing access to records addresses cooperation with the auditor but does not specifically assert that all transactions were captured in the accounting system.', 'medium', 2),

-- Q7: medium / L3 — Inconsistencies between representations and other evidence
(1, 'Written Representations', 'During the audit of Oakridge Technologies for the year ended December 31, 2025, the engagement team at Prescott & Hayes CPA discovers that management''s representation letter states no related party transactions occurred, but audit evidence reveals a $750,000 consulting contract with the CEO''s spouse. The engagement partner should first:', '["Accept the representation letter and disclose the related party transaction in an emphasis-of-matter paragraph", "Withdraw from the engagement immediately due to management''s apparent dishonesty", "Investigate the inconsistency and consider the reliability of all management representations", "Issue a qualified opinion noting the conflict between the representation and the evidence obtained"]'::jsonb, 2, 'Under AU-C 580.18, if the auditor identifies inconsistencies between management''s written representations and other audit evidence, the auditor should investigate the matter and reconsider the reliability of all representations made by management. This requires professional judgment, not an automatic withdrawal or immediate opinion modification. Unlike choice B suggests, the auditor must first investigate before concluding on the appropriate response.', 'medium', 3),

-- Q8: hard / L4 — Group audit component management representations
(1, 'Written Representations', 'Sterling & Associates serves as the group engagement partner for the consolidated audit of Pinnacle Holdings for the year ended December 31, 2025. Pinnacle has three wholly owned subsidiaries, each audited by different component auditors. The group engagement partner is determining whether to obtain separate representation letters from each subsidiary''s management. Under AU-C 600 and AU-C 580, this decision should be based on:', '["Whether the subsidiaries are located in the same jurisdiction as the parent company", "Whether the combined revenue of the subsidiaries exceeds 75% of group revenue", "Whether the component auditors have already obtained representation letters from subsidiary management", "The nature and extent of the group engagement partner''s involvement with the components and the assessed risk at the component level"]'::jsonb, 3, 'Under AU-C 600.40 and AU-C 580, the group engagement partner considers the nature and extent of involvement with component auditors and the assessed risks at the component level when determining whether separate representation letters from component management are necessary. This is a judgment-based decision. Unlike choice B suggests, there is no prescribed revenue percentage that triggers the requirement for component-level representation letters.', 'hard', 4),

-- Q9: easy / L1 — Accounting policies representation
(1, 'Written Representations', 'Under AU-C 580, what must management represent regarding accounting policies?', '["That the selection and application of accounting policies are appropriate", "That accounting policies have remained unchanged from the prior year", "That the entity''s accounting policies exceed industry standards", "That all accounting policies have been approved by the audit committee"]'::jsonb, 0, 'Under AU-C 580.11, management must represent that the selection and application of accounting policies are appropriate for the entity''s financial reporting framework. This does not require policies to be unchanged or to exceed any standard. Unlike choice B suggests, management may appropriately change accounting policies; the representation addresses appropriateness of selection, not consistency with the prior year.', 'easy', 1),

-- Q10: medium / L3 — Going concern representations
(1, 'Written Representations', 'During the December 31, 2025 audit of Summit Holdings, the engagement team at Caldwell & Foster CPA identifies conditions raising substantial doubt about Summit''s ability to continue as a going concern. Management believes the entity will survive through a planned equity infusion. The engagement partner requests a specific going concern representation. This representation should include management''s:', '["Guarantee that the entity will continue operations for at least 12 months after the balance sheet date", "Plans and assessment of the entity''s ability to continue as a going concern and the adequacy of related disclosures", "Certification that no going concern uncertainty exists that would require disclosure", "Commitment to obtain a letter of credit from a financial institution to support ongoing operations"]'::jsonb, 1, 'Under AU-C 580.A11 and AU-C 570, when going concern conditions exist, the auditor should request representations that include management''s plans to address the conditions and its assessment of the entity''s ability to continue as a going concern, along with disclosure adequacy. Unlike choice A suggests, management cannot guarantee future operations — the representation addresses plans and assessments, not guarantees of continued existence.', 'medium', 3),

-- Q11: hard / L3 — Litigation, claims, and assessments representation
(1, 'Written Representations', 'Riverdale Corp. is undergoing the December 31, 2025 audit conducted by Morrison & Blake CPA. The auditor has sent an attorney letter and received a response indicating three pending lawsuits with estimated exposure of $4.2 million. The engagement partner reviews the management representation letter to confirm it addresses litigation. This representation should state that management has:', '["Authorized external legal counsel to communicate all potential litigation matters directly to the auditor", "Accrued the full $4.2 million estimated exposure in the current-period financial statements", "Disclosed all known actual or possible litigation, claims, and assessments whose effects should be considered in the financial statements", "Obtained written confirmation from legal counsel that no additional pending litigation exists beyond the three cases"]'::jsonb, 2, 'Under AU-C 580.11, the representation letter should include management''s acknowledgment that it has disclosed all known actual or possible litigation, claims, and assessments whose effects should be considered when preparing financial statements. This focuses on completeness of disclosure rather than accrual amounts. Unlike choice B suggests, the representation addresses disclosure completeness, not a requirement to accrue a specific dollar amount, which depends on ASC 450 loss contingency criteria.', 'hard', 3),

-- Q12: medium / L2 — Compliance with laws and regulations
(1, 'Written Representations', 'During the audit of Baxter Engineering for the year ended December 31, 2025, the engagement team at Whitfield & Grant CPA prepares a draft representation letter. The senior auditor asks which representation addresses the risk that noncompliance with laws or regulations could materially affect the financial statements. Under AU-C 580, management should represent that:', '["The entity has engaged external legal counsel to monitor compliance with all applicable laws", "No regulatory enforcement actions have been filed against the entity during the audit period", "The entity maintains a formal compliance program reviewed annually by the board of directors", "All known instances of noncompliance or suspected noncompliance with laws and regulations have been disclosed to the auditor"]'::jsonb, 3, 'Under AU-C 580.11 and AU-C 250, management should represent that all known instances of noncompliance or suspected noncompliance with laws and regulations whose effects should be considered when preparing financial statements have been disclosed. Unlike choice A suggests, engaging legal counsel is a business decision but is not the specific representation required — disclosure of known noncompliance is the key element.', 'medium', 2),

-- Q13: medium / L3 — Representations from those charged with governance
(1, 'Written Representations', 'During the audit of Crestview Medical Group for the year ended December 31, 2025, the engagement partner at Eastwood & Hall CPA determines that certain matters within the board of directors'' direct knowledge may not be fully known to management. The partner considers obtaining written representations directly from those charged with governance. Under AU-C 580, this is appropriate when:', '["The auditor determines that representations from those charged with governance are necessary to support representations made by management", "Management and governance have conflicting views, and the auditor must choose which party to believe", "The entity''s governance structure has more than five board members", "The auditor wants to bypass management entirely to obtain more reliable audit evidence"]'::jsonb, 0, 'Under AU-C 580.13, the auditor may request written representations from those charged with governance when matters are within their direct responsibility or knowledge and such representations are necessary to support management''s representations. This is a targeted supplement, not a replacement. Unlike choice D suggests, the purpose is not to bypass management but to obtain representations about matters specifically within governance''s purview.', 'medium', 3),

-- Q14: easy / L2 — Access to records representation
(1, 'Written Representations', 'The controller of Ironbridge Corp. asks the engagement team at Fielding & Associates what the management representation letter should state regarding the auditor''s access to information. Under AU-C 580, management should represent that it has:', '["Granted the auditor unlimited access to all entity information, including attorney-client privileged communications", "Provided the auditor with access to all information relevant to the preparation of the financial statements", "Given the auditor administrative access to all electronic accounting systems and databases", "Made all employees available for interview at any time during the audit engagement"]'::jsonb, 1, 'Under AU-C 580.11, management must represent that it has provided the auditor with all information relevant to the preparation and fair presentation of the financial statements, including access to all relevant records, documentation, and personnel. Unlike choice A suggests, this does not extend to attorney-client privileged communications — the representation covers information relevant to the financial statements, not all entity information without limitation.', 'easy', 2),

-- Q15: medium / L3 — Management bias in accounting estimates
(1, 'Written Representations', 'During the audit of Hartfield Brands for the year ended December 31, 2025, the engagement team at Dawson & Palmer CPA evaluates a $3.8 million allowance for doubtful accounts. The auditor suspects management may have intentionally understated the allowance to improve reported earnings. The engagement partner considers whether the representation letter adequately addresses this risk. Under AU-C 580, the letter should include management''s acknowledgment that:', '["All accounting estimates have been reviewed and approved by the audit committee before year-end", "External valuation specialists were consulted for all estimates exceeding $1 million", "The methods, data, and significant assumptions used in making accounting estimates are reasonable in the context of the applicable financial reporting framework", "All estimates have been calculated using the same methodology as the prior year without modification"]'::jsonb, 2, 'Under AU-C 580.11 and AU-C 540, the representation letter should include management''s acknowledgment that the methods, data, and significant assumptions used in accounting estimates are reasonable within the applicable financial reporting framework. This provides a basis for evaluating potential bias. Unlike choice D suggests, consistency of methodology is not the required representation — reasonableness of methods, data, and assumptions is the standard, regardless of whether methodology changed.', 'medium', 3),

-- Q16: hard / L4 — Evaluating representations when doubting management integrity
(1, 'Written Representations', 'During the December 31, 2025 audit of Lockwood & Pierce Inc., the engagement partner at Greystone CPA discovers that the CEO provided a signed representation letter asserting no knowledge of fraud, but subsequently learns the CEO was previously sanctioned by the SEC for financial reporting fraud at a prior employer. The engagement partner must evaluate the effect on the audit. The most appropriate course of action is to:', '["Accept the representation letter at face value because AU-C 580 does not require background checks on management", "Obtain a supplemental representation letter signed solely by the CFO to replace the CEO''s representations", "Disclose the CEO''s history in an other-matter paragraph in the auditor''s report", "Assess the implications for management integrity, reconsider the reliability of all representations, and evaluate the effect on the audit as a whole"]'::jsonb, 3, 'Under AU-C 580.19-.20 and AU-C 240, when the auditor has concerns about management integrity or ethical values, the auditor must consider the implications for the reliability of representations and other audit evidence. This requires a holistic reassessment of the audit, not merely a procedural fix. Unlike choice B suggests, substituting a different signer does not address the fundamental concern about the integrity of the management team making the representations.', 'hard', 4),

-- Q17: hard / L4 — Side agreements or undisclosed arrangements
(1, 'Written Representations', 'During the audit of Wellington Services for the year ended December 31, 2025, the engagement team at Harmon & Associates discovers a verbal side agreement between Wellington and a major customer that modifies payment terms of a $5.6 million contract. The side agreement was not reflected in the financial statements or disclosed to the auditor. Management claims the arrangement is immaterial. The auditor should:', '["Evaluate whether the side agreement represents an undisclosed arrangement that could constitute a material misstatement and assess the impact on management''s other representations", "Accept management''s materiality assessment and note the side agreement in the audit workpapers for future reference", "Request only that management add the side agreement to the representation letter for the subsequent year''s audit", "Report the side agreement to the audit committee but take no further action regarding the current-year financial statements"]'::jsonb, 0, 'Under AU-C 580.18-.20, when the auditor discovers matters not disclosed despite management''s representations about completeness, the auditor must evaluate the potential misstatement, reconsider the reliability of management''s representations, and determine the effect on the audit opinion. Undisclosed side agreements raise serious concerns about management''s candor. Unlike choice B suggests, the auditor cannot simply accept management''s materiality claim — independent evaluation of the financial impact is required.', 'hard', 4),

-- Q18: medium / L3 — Title to assets and rights/obligations assertion
(1, 'Written Representations', 'During the December 31, 2025 audit of Silverstone Group, the engagement team at Lancaster & Pierce CPA reviews the representation letter and notes management''s representation about the entity''s assets. The senior auditor asks what specific assertion this representation about satisfactory title to owned assets primarily supports. Under AU-C 580, this representation supports the assertion of:', '["Existence — confirming that the assets are real and physically present", "Rights and obligations — confirming the entity''s ownership interest in the recorded assets", "Valuation — confirming that assets are recorded at appropriate carrying amounts", "Completeness — confirming that all assets owned by the entity are recorded"]'::jsonb, 1, 'Under AU-C 580 and AU-C 315, management''s representation that the entity has satisfactory title to owned assets directly supports the rights and obligations assertion, which addresses whether the entity holds or controls the rights to assets. Unlike choice A suggests, the existence assertion addresses whether assets are real, not whether the entity owns them — an asset can exist without the entity having legal title to it.', 'medium', 3),

-- Q19: medium / L2 — Additional representations required by other AU-C sections
(1, 'Written Representations', 'While preparing the representation letter for the December 31, 2025 audit of Norwood Enterprises, the engagement partner at Redmond & Cole CPA reviews other AU-C sections to determine whether additional representations beyond those in AU-C 580 are needed. The partner identifies that additional representations may be required by:', '["The entity''s corporate bylaws and articles of incorporation", "The AICPA''s peer review standards applicable to the audit firm", "Other AU-C sections addressing specific audit areas such as estimates, related parties, or subsequent events", "The engagement letter previously signed by management at the start of the audit"]'::jsonb, 2, 'Under AU-C 580.A8, other AU-C sections require or contemplate additional written representations about specific matters. For example, AU-C 540 (estimates), AU-C 550 (related parties), AU-C 560 (subsequent events), and AU-C 250 (laws and regulations) may each trigger specific representations. Unlike choice A suggests, corporate bylaws do not dictate the content of the management representation letter — professional auditing standards determine what representations are required.', 'medium', 2),

-- Q20: hard / L4 — Uncorrected misstatements specific representation
(1, 'Written Representations', 'During the audit of Ridgepoint Capital for the year ended December 31, 2025, the engagement team at Sheffield & Tate CPA identifies three uncorrected misstatements totaling $285,000, which are individually and in the aggregate below materiality of $500,000. Management declines to correct them. Before the representation letter is finalized, the partner must ensure it includes a specific representation. Management should represent that:', '["The three misstatements have been evaluated by the audit committee and deemed immaterial", "The uncorrected misstatements were caused by system limitations beyond management''s control", "The engagement team has agreed that the misstatements are immaterial and no further action is needed", "It believes the effects of the uncorrected misstatements are immaterial, both individually and in the aggregate, to the financial statements as a whole"]'::jsonb, 3, 'Under AU-C 580.11 and AU-C 450.14, the representation letter must include a summary of uncorrected misstatements and management''s representation that it believes their effects are immaterial, both individually and in the aggregate, to the financial statements as a whole. Unlike choice C suggests, the auditor does not "agree" the misstatements are immaterial — it is management''s acknowledgment of responsibility for this judgment that the standard requires.', 'hard', 4),

-- Q21: hard / L4 — Contradictory evidence discovered late in engagement
(1, 'Written Representations', 'Three days before issuing the auditor''s report for Ashwood Financial''s December 31, 2025 audit, the engagement partner at Wallace & Burns CPA receives a whistleblower complaint alleging that the CFO directed staff to omit $1.2 million in accrued liabilities. Management''s signed representation letter states all liabilities have been properly recorded. The auditor''s first priority is to:', '["Investigate the allegation, evaluate the reliability of all management representations, and determine whether additional audit procedures are necessary before issuing the report", "Issue the report as planned because the representation letter was already signed and constitutes sufficient evidence", "Withdraw the previously signed representation letter and request a new letter excluding the CFO as a signatory", "Immediately notify the SEC of the potential fraud before completing any further audit work"]'::jsonb, 0, 'Under AU-C 580.18-.20 and AU-C 240, when the auditor discovers information contradicting management''s written representations, the auditor must investigate the matter, reassess the reliability of all representations, and determine whether additional procedures are necessary. The report should not be issued until the allegation is resolved. Unlike choice B suggests, a previously signed representation letter does not override contradictory evidence — the auditor must address the inconsistency before finalizing the report.', 'hard', 4),

-- Q22: medium / L2 — Internal control responsibilities representation
(1, 'Written Representations', 'During preparation of the management representation letter for the December 31, 2025 audit of Brightwater Holdings, the engagement team at Pemberton & Ross CPA includes a representation about internal controls. The controller asks what this representation specifically addresses. Under AU-C 580, management should acknowledge responsibility for:', '["Designing internal controls that guarantee the prevention of all material misstatements", "The design, implementation, and maintenance of internal control relevant to the preparation of financial statements", "Hiring a third-party specialist to evaluate and certify the effectiveness of all internal controls annually", "Eliminating all identified control deficiencies before the end of each fiscal year"]'::jsonb, 1, 'Under AU-C 580.11 and AU-C 210, the management representation letter includes an acknowledgment of management''s responsibility for the design, implementation, and maintenance of internal control relevant to the preparation and fair presentation of financial statements. Unlike choice A suggests, internal controls provide reasonable, not absolute, assurance — no system can guarantee prevention of all misstatements.', 'medium', 2),

-- Q23: easy / L1 — Purpose of obtaining written representations
(1, 'Written Representations', 'What is the primary purpose of obtaining written representations from management?', '["To transfer responsibility for the financial statements from management to the auditor", "To satisfy regulatory agencies that require the auditor to obtain management''s written consent", "To obtain necessary audit evidence and document management''s acknowledgment of its responsibilities", "To provide legal protection for the auditor in the event of a future lawsuit"]'::jsonb, 2, 'Under AU-C 580.03-.04, the primary purpose of written representations is twofold: to obtain necessary audit evidence that supports the auditor''s conclusions and to document management''s acknowledgment of its responsibilities for the financial statements. Unlike choice A suggests, written representations do not transfer responsibility — management retains responsibility for the financial statements regardless of whether representations are provided.', 'easy', 1),

-- Q24: medium / L2 — Documentation requirements for written representations
(1, 'Written Representations', 'After completing the December 31, 2025 audit of Thornhill Corp., the engagement partner at Ashford & Lane CPA reviews the workpapers to ensure proper documentation of written representations. A staff auditor asks how the management representation letter should be documented. Under AU-C 580, the auditor should:', '["Retain only a summary of the key representations rather than the full letter to reduce workpaper volume", "Document oral representations in a memo if management prefers not to provide a written letter", "File the representation letter only if it contains representations that differ from the standard template", "Include the signed management representation letter in the audit documentation as evidence of the representations obtained"]'::jsonb, 3, 'Under AU-C 580.A25 and AU-C 230, the signed management representation letter itself becomes part of the audit documentation. It serves as evidence that written representations were obtained as required. Unlike choice A suggests, retaining only a summary would not satisfy the documentation standard — the complete signed letter must be included to demonstrate compliance with AU-C 580 and to support the audit evidence obtained.', 'medium', 2),

-- Q25: easy / L1 — Pledged or collateralized assets
(1, 'Written Representations', 'Under AU-C 580, what should management represent regarding liens or encumbrances on assets?', '["That all liens, pledges, or encumbrances on assets have been disclosed", "That no assets have been pledged as collateral during the current year", "That the entity has obtained insurance coverage for all pledged assets", "That management intends to release all liens before the next fiscal year-end"]'::jsonb, 0, 'Under AU-C 580.11, the management representation letter should include a representation that all liens, pledges, and encumbrances on assets have been disclosed to the auditor. This supports the completeness of disclosure in the financial statements. Unlike choice B suggests, the representation does not assert that no assets have been pledged — rather, it confirms that any existing pledges have been properly disclosed.', 'easy', 1),

-- Q26: easy / L1 — Commitments and guarantees
(1, 'Written Representations', 'Under AU-C 580, what must management represent about contractual commitments?', '["That the entity has no material commitments or contingencies of any kind", "That all contractual commitments and guarantees that could affect the financial statements have been disclosed", "That all commitments have been formally approved by the board of directors", "That the entity intends to fulfill all contractual commitments within the next 12 months"]'::jsonb, 1, 'Under AU-C 580.11, management should represent that all commitments, contractual obligations, and guarantees that could materially affect the financial statements have been disclosed. This addresses completeness of disclosures about off-balance-sheet arrangements and obligations. Unlike choice A suggests, the representation is about disclosure completeness, not an assertion that no commitments exist — entities routinely have material commitments that require disclosure.', 'easy', 1),

-- Q27: medium / L3 — Initial vs. recurring audit effect on representations
(1, 'Written Representations', 'Crawford & Hughes CPA has been engaged to perform the initial audit of Copperfield Ltd. for the year ended December 31, 2025. The predecessor auditor audited the prior year. The engagement partner considers how the initial engagement affects the management representation letter compared to a recurring engagement. For an initial audit, the representation letter should:', '["Be limited to matters occurring only after the predecessor auditor''s report date", "Waive representations about prior-period balances because those were the predecessor''s responsibility", "Cover all periods referred to in the auditor''s report, which may require representations about matters predating the current engagement", "Include a representation from the predecessor auditor confirming the accuracy of prior-period workpapers"]'::jsonb, 2, 'Under AU-C 580.15, the representation letter addresses all periods referred to in the auditor''s report. In an initial engagement with comparative financial statements, management must provide representations covering prior periods even though a predecessor auditor conducted that audit. Unlike choice B suggests, the current auditor cannot waive prior-period representations — management''s responsibility for those financial statements continues regardless of which auditor performed the engagement.', 'medium', 3),

-- Q28: medium / L2 — Knowledge of noncompliance with laws
(1, 'Written Representations', 'The engagement team at Hayward & Sterling CPA is preparing the representation letter for the December 31, 2025 audit of Drummond Group. The controller reviews the draft and questions a representation about noncompliance with laws and regulations. Under AU-C 580, this representation should specifically state that management has disclosed:', '["A complete list of every federal, state, and local regulation applicable to the entity", "The identity of the entity''s regulatory compliance officer and their qualifications", "Copies of all regulatory filings made by the entity during the audit period", "All known instances of noncompliance or suspected noncompliance with laws and regulations whose effects should be considered in preparing the financial statements"]'::jsonb, 3, 'Under AU-C 580.11, the representation letter requires management to disclose all known instances of noncompliance, or suspected noncompliance, with laws and regulations whose effects should be considered when preparing financial statements. This is targeted at financially relevant noncompliance. Unlike choice A suggests, management is not required to list every applicable regulation — only to disclose known or suspected noncompliance that affects the financial statements.', 'medium', 2),

-- Q29: easy / L1 — Requesting additional representations beyond required
(1, 'Written Representations', 'Under AU-C 580, when may an auditor request additional written representations beyond those specifically required?', '["Whenever the auditor considers it necessary to support other audit evidence obtained during the engagement", "Only when the engagement letter specifically authorizes the auditor to request additional representations", "Only when the audit committee has approved the specific additional representations in advance", "Only when the entity is a public company subject to PCAOB auditing standards"]'::jsonb, 0, 'Under AU-C 580.A8 and .12, the auditor may request additional written representations about specific matters whenever the auditor considers them necessary to support other audit evidence. There is no requirement for prior authorization from the engagement letter or audit committee. Unlike choice B suggests, the auditor''s professional judgment about what representations are needed is not constrained by the terms of the engagement letter.', 'easy', 1),

-- Q30: medium / L3 — Reasonableness of assumptions in estimates
(1, 'Written Representations', 'During the audit of Langford Corp. for the year ended December 31, 2025, the engagement team at Crawford & Hughes CPA evaluates a $6.1 million goodwill impairment model that uses projected revenue growth of 12% and a discount rate of 8%. The engagement partner reviews the representation letter to determine whether it adequately addresses these inputs. Under AU-C 580 and AU-C 540, the representation about accounting estimates should confirm that:', '["An independent valuation expert has verified all assumptions used in the impairment model", "The significant assumptions used in making the accounting estimate are reasonable", "The projected revenue growth rate has been achieved in at least three of the past five years", "The discount rate was selected from a published industry benchmark without modification"]'::jsonb, 1, 'Under AU-C 580.11 and AU-C 540, the representation letter should include management''s acknowledgment that the significant assumptions used in making accounting estimates, including fair value measurements, are reasonable. This encompasses both the growth rate and discount rate used in the impairment model. Unlike choice A suggests, independent verification is not required — the standard requires management to represent the reasonableness of assumptions, not that they were externally validated.', 'medium', 3)
;

COMMIT;
